import {REVIVE_BADGES,reviveUpgrade,dailyObjectives,ensureDaily,expeditionSummary,summaryKey} from './progression-meta.mjs';
import {applyAction,PREPARATION_ACTIONS} from './actions.mjs';
import {createSyncClient} from './sync-client.mjs';
import {fighterEffects,weatherEffect} from './effects.mjs';
import {configureEvolution,evolutionOptions,autoEvolve,evolveTo} from './evolution.mjs';
import {ROUTE_THEMES,damageTone,visibleDamageEvents,campMotion} from './visuals.mjs';
import {initial,makeRoutes,tier,acquire,strength,slots,begin,advance,openPack,openPacks,gym,GYMS,RANKS,TEAM_BADGES,gymProgress,gymUnlocked,gymLevel,gymPool,gymSpecies,gymPackSources,routeUnlocked,teamSpeed,IV_NAMES,TYPE_NAMES,pwt,migrate,chooseStarter,fighter,encounterDelay,attackCharge,routeSpecies,quickStart,xpProgress,configureCombat,moveById,learnedMoves,recommendedMoves,ensureMoves,moveScore,moveCharge,levelRange,levelDistribution} from './engine.mjs';
const catalog=(await fetch('./catalog.json').then(r=>r.json())).map(p=>({...p,bst:p.stats.reduce((a,b)=>a+b,0)}));
const byId=Object.fromEntries(catalog.map(p=>[p.id,p]));const routes=makeRoutes(catalog);const packSources=[...routes,...gymPackSources(catalog)];
const chart=await fetch('./type-chart.json').then(r=>r.json());const moves=await fetch('./moves.json').then(r=>r.json());configureCombat(catalog,moves);configureEvolution(catalog,await fetch('./evolutions.json').then(r=>r.json()));
let cloudUser=null,cloudRevision=0,cloudBusy=false,cloudReady=false,cloudError='',clockOffset=0;
const gameNow=()=>Date.now()+clockOffset;
let s=initial();
try{const response=await fetch('/api/game',{cache:'no-store'}),data=await response.json();if(response.ok){s=data.state;cloudUser=data.user;cloudRevision=data.revision;clockOffset=data.now-Date.now();cloudReady=true;}else if(response.status!==401)cloudError=data.error||'No se pudo cargar la partida';}catch{cloudError='No se pudo conectar. Comprueba tu conexión.';}
const starters=catalog.filter(p=>[1,4,7,152,155,158,252,255,258,387,390,393,495,498,501,650,653,656,722,725,728,810,813,816,906,909,912].includes(p.id));
let navigationRevision=0,commandNavigation=0,renderedNavView=null,renderedDailyDay=null,pointerHeld=false,interactionUntil=0;
let view='home',query='',filter='all',gen='all',page=0,lastAutoSave=0,editTeamId=null,teamSort='pwt',teamType='all',teamQuery='';const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const expandedTeams=new Set();
const labels={home:'⌂  Campamento',teams:'⚑  Expediciones',routes:'⌖  Rutas',gyms:'◈  Gimnasios',packs:'▱  Sobres',dex:'▦  Pokédex',upgrades:'✚  Mejoras',daily:'✓  Misiones',account:'◉  Cuenta',wiki:'▤  Wiki'};
const name=p=>p.name.replaceAll('-',' ');const sprite=(p,shiny=false)=>`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${shiny?'shiny/':''}${p.id}.png`;const art=p=>sprite(p);
const img=(p,shiny=false)=>`<img loading="lazy" src="${sprite(p,shiny)}" alt="${name(p)}" onerror="this.style.opacity='.15'">`;
const toast=t=>{const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',6000)};
let syncState={busy:false,pending:false,critical:false,error:false};
function save(){const label=document.querySelector('#saved');if(label)label.textContent=cloudError||syncState.error?'Sin conexión · cambios pendientes':syncState.busy?'Guardando…':syncState.pending?'Cambios pendientes…':cloudReady?'Guardado en tu cuenta':'Inicia sesión para jugar';}
function acceptCloud(data){s=data.state;cloudRevision=data.revision;clockOffset=data.now-Date.now();if(data.user)cloudUser=data.user;cloudReady=true;cloudError='';advance(s,routes,gameNow(),chart);}
const sync=createSyncClient({
 revision:()=>cloudRevision,
 request:operation=>fetch('/api/game',{method:'POST',headers:{'Content-Type':'application/json','X-Game-Client':'expedition-v13'},body:JSON.stringify(operation)}),
 accept:acceptCloud,
 preview:action=>applyAction(s,action,{catalog,byId,routes,chart,now:gameNow()}),
 notify:toast,
 changed:status=>{const wasBusy=syncState.busy;syncState=status;cloudBusy=status.busy;save();if(wasBusy&&!status.busy&&modal.open&&document.querySelector('#team-sort'))teamEditor(editTeamId);},
 completed:(action,result)=>{if(action.type==='open'){const batch=result.batch;batch.results=batch.results.map(x=>({...x,p:byId[x.pokemonId]}));showPackResults(batch);}else{if(commandNavigation===navigationRevision){modal.close();if(['begin','gymBegin','quick'].includes(action.type))view='teams';}if(action.type==='starter')toast('¡Comienza tu aventura!');if(result.message)toast(result.message);}}
});
async function refreshCloud(){await sync.refresh(async()=>{const response=await fetch('/api/game',{cache:'no-store'}),data=await response.json();if(!response.ok){if(response.status===401){cloudReady=false;cloudUser=null;}throw Error(data.error==='AUTH_REQUIRED'?'Inicia sesión para continuar':data.error);}return data;});render();save();}
async function sendCommand(action){
 if(!cloudReady)return toast('Inicia sesión para continuar');
 if(PREPARATION_ACTIONS.has(action.type)){if(action.type==='setRoute')teamSort='route';sync.edit(action);render();if(['pick','order','setRoute','autoTeam'].includes(action.type))teamEditor(Number(action.id));else if(['equip','recommend'].includes(action.type))moveEditor(Number(action.id));save();return;}
 if(syncState.critical)return;commandNavigation=navigationRevision;const operation=sync.flush(action);render();save();await operation;render();save();
}
const owned=()=>Object.entries(s.collection);const totalPacks=()=>Object.values(s.packs).reduce((a,b)=>a+b,0);const teamPower=t=>t.ids.reduce((a,f)=>a+strength(s.collection[f],byId[s.collection[f].id]),0);
function chargePercent(f){return Math.max(0,Math.min(100,(gameNow()-(f.chargeStarted||gameNow()))/(f.chargeDuration||1)*100));}
function moveEffect(m){const effects=[];if(m.key==='leech-seed')effects.push('drena hasta 1/8 de los PS máximos del rival al actuar; cura los PS quitados');else if(m.key==='ingrain'||m.key==='aqua-ring')effects.push('recupera 1/16 de PS máximos después de actuar; no se acumula al repetir');else if(m.key==='rest')effects.push('recupera PS y duerme 2 acciones');else if(m.ailment>0)effects.push('estado');if(m.changes?.length)effects.push(m.changes.map(([stat,n])=>['PS','Ataque','Defensa','At. esp.','Def. esp.','Velocidad','Precisión','Evasión'][stat-1]+' '+(n>0?'+':'')+n).join(', '));if(m.healing)effects.push('cura '+m.healing+'%');if(m.drain>0)effects.push('absorbe '+m.drain+'%');if(m.drain<0)effects.push('retroceso');if(m.flinch)effects.push('retroceso rival');return effects.join(' · ')||'Daño';}
function chooseRoute(id){show(`${setupSteps(1)}<span class="eyebrow">PASO 1 · DESTINO</span><h2>Elige la ruta del equipo ${id+1}</h2><div class="route-choice-grid">${routes.map(r=>{const profile=routeProfile(s,r);return `<button class="route-choice" data-action="setRoute" data-id="${id}" data-route="${r.id}" ${!routeUnlocked(s,r)?'disabled':''}>${routeBanner(r.id,'RUTA '+(r.id+1))}<span class="route-choice-body"><strong>${r.name}</strong><small>Nivel ${rangeLabel(r)} · Vel. zona ${r.speed}</small><span class="route-type-list">${profile.types.slice(0,3).map(t=>typeBadge(t.type,TYPE_NAMES[t.type],Math.round(t.chance*100)+'%')).join('')}</span><span class="route-choice-bottom">${routeUnlocked(s,r)?'Elegir ruta →':'🔒 '+r.badge+' medallas'}</span></span></button>`;}).join('')}</div>`);}
function teamEditor(id){editTeamId=id;const destination=routes[s.teams[id].plannedRoute],ranked=destination?rankRouteCandidates(s,id,destination,byId,chart):null,routeScores=new Map(ranked?.candidates.map(c=>[c.family,c.score])||[]),routeBonuses=new Map(ranked?.candidates.map(c=>[c.family,Math.round((c.affinity-1)*100)])||[]);const other=new Set(s.teams.filter((t,j)=>j!==id).flatMap(t=>t.ids));let list=owned().filter(([,c])=>(teamType==='all'||byId[c.id].types.includes(Number(teamType)))&&name(byId[c.id]).includes(teamQuery.toLowerCase()));const value=([,c])=>teamSort==='route'?(routeScores.get(Number(byId[c.id].family))||0):teamSort==='level'?c.level:teamSort==='speed'?fighter(byId[c.id],c).stats[5]:pwt(c,byId[c.id]);list.sort((a,b)=>teamSort==='name'?name(byId[a[1].id]).localeCompare(name(byId[b[1].id])):value(b)-value(a)||a[1].id-b[1].id);show(`${setupSteps(2)}<span class="eyebrow">PASO 2 · EQUIPO ${id+1}</span><h2>${destination?destination.name:'Orden de combate'}</h2>${destination?`<div class="route-team-profile">${routeBanner(destination.id)}<p>Nivel ${rangeLabel(destination)} · tipos frecuentes</p><div>${ranked.types.slice(0,4).map(t=>typeBadge(t.type,TYPE_NAMES[t.type],(t.chance*100).toFixed(0)+'%')).join(' ')}</div><div class="actions"><button data-action="autoTeam" data-id="${id}">✦ Equipo automático recomendado</button><button class="secondary" data-action="send" data-id="${id}">Cambiar ruta</button></div></div>`:''}<p class="small">Orden de relevo · el primero combate hasta caer.</p><div class="team-order">${s.teams[id].ids.map((f,i)=>`<div class="order-slot"><span>${i+1}</span>${img(byId[s.collection[f].id],s.collection[f].shiny)}<small>${name(byId[s.collection[f].id])}</small><div><button class="secondary" data-action="order" data-id="${id}" data-index="${i}" data-direction="-1" ${i===0?'disabled':''}>←</button><button class="secondary" data-action="order" data-id="${id}" data-index="${i}" data-direction="1" ${i===s.teams[id].ids.length-1?'disabled':''}>→</button></div></div>`).join('')}${Array.from({length:6-s.teams[id].ids.length},(_,j)=>`<div class="order-slot empty-slot"><span>${s.teams[id].ids.length+j+1}</span><b>＋</b><small>Espacio libre</small></div>`).join('')}</div><div class="search"><input id="team-query" placeholder="Buscar Pokémon" value="${teamQuery.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}"><select id="team-sort">${[...(destination?[['route','Rendimiento en esta ruta']]:[]),['pwt','PWT: mayor primero'],['level','Nivel: mayor primero'],['speed','Velocidad: mayor primero'],['name','Nombre: A–Z']].map(([v,n])=>`<option value="${v}" ${teamSort===v?'selected':''}>${n}</option>`).join('')}</select><select id="team-type"><option value="all">Todos los tipos</option>${TYPE_NAMES.slice(1).map((n,i)=>`<option value="${i+1}" ${teamType==i+1?'selected':''}>${n}</option>`).join('')}</select></div><div class="picker">${list.map(([f,c])=>`<button data-action="pick" data-id="${id}" data-family="${f}" class="${s.teams[id].ids.includes(Number(f))?'selected':''}" ${other.has(Number(f))?'disabled':''} aria-pressed="${s.teams[id].ids.includes(Number(f))}" ${other.has(Number(f))?'title="Asignado a otro equipo"':''}><span class="candidate-sprite">${img(byId[c.id],c.shiny)}</span><strong>${name(byId[c.id])}</strong><span class="candidate-types">${byId[c.id].types.map(t=>typeBadge(t,TYPE_NAMES[t])).join('')}</span><small>Nv. ${c.level} · Vel. ${fighter(byId[c.id],c).stats[5]}</small>${destination?`<span class="candidate-score"><small>Índice de ruta</small><b>${routeScores.get(Number(f))||0}</b><span class="affinity ${((routeBonuses.get(Number(f))||0)>=0)?'positive':'negative'}" title="Ajuste del rendimiento por efectividad y resistencia de tipos">Tipos ${(routeBonuses.get(Number(f))||0)>=0?'+':''}${routeBonuses.get(Number(f))||0}%</span></span>`:`<small>PWT ${pwt(c,byId[c.id])}</small>`}</button>`).join('')}</div>${destination?`<div class="setup-footer"><span>${s.teams[id].ids.length}/6 compañeros · ${destination.name}</span><button data-action="begin" data-id="${id}" data-route="${destination.id}" ${!s.teams[id].ids.length?'disabled':''}>Confirmar equipo e iniciar →</button></div>`:''}`);}
function moveEditor(id){const p=byId[id],c=s.collection[p.family];if(!c)return;ensureMoves(c,p);const f=fighter(p,c),recommended=new Set(recommendedMoves(c,p)),blocked=s.teams.some(t=>t.run?.status==='active'&&t.ids.includes(p.family));const learned=c.learnedMoves.map(moveById).sort((a,b)=>(c.equippedMoves.includes(a.id)?c.equippedMoves.indexOf(a.id):10)-(c.equippedMoves.includes(b.id)?c.equippedMoves.indexOf(b.id):10)||moveScore(b,p,c)-moveScore(a,p,c));show(`<span class="eyebrow">MOVIMIENTOS · ${name(p)}</span><h2>${c.equippedMoves.length}/4 equipados</h2><p>${c.autoMoves?'Recomendación automática activa: se equipa al aprender movimientos.':'Selección manual: los aprendizajes se guardan sin cambiar tus cuatro espacios.'}</p><button data-action="recommend" data-id="${id}" ${blocked?'disabled':''}>Equipar recomendación automática</button><div class="move-list">${learned.map(m=>`<div class="move-row ${c.equippedMoves.includes(m.id)?'equipped':''}"><div><strong>${c.equippedMoves.includes(m.id)?(c.equippedMoves.indexOf(m.id)+1)+'. ':''}${m.name}</strong>${recommended.has(m.id)?'<span class="tag green">Recomendado</span>':''}<p>${typeBadge(m.type,TYPE_NAMES[m.type])} · ${m.category===2?'Físico':'Especial'} · Potencia ${m.power}${m.adapted?' (apoyo adaptado)':''}<br>Carga ${(moveCharge(f,m)/1000).toFixed(2)} s · Precisión ${m.accuracy}%<br>${moveEffect(m)}</p></div><button class="${c.equippedMoves.includes(m.id)?'secondary':''}" data-action="equip" data-id="${id}" data-move="${m.id}" ${blocked?'disabled':''}>${c.equippedMoves.includes(m.id)?'Desequipar':'Equipar'}</button></div>`).join('')}</div><details class="future-moves"><summary>Próximos aprendizajes</summary><p>${(p.learnset||[]).filter(([lv])=>lv>c.level).map(([lv,mid])=>'Nv. '+lv+': '+moveById(mid).name+(p.trainingMoves?.includes(mid)?' (entrenamiento)':'')).join(' · ')||'Ya aprendió todos sus movimientos por nivel.'}</p></details><p class="small">Estados, cambios de atributos de −6 a +6, curación, absorción, retroceso, barreras y climas adaptados. Los efectos especiales únicos todavía son una adaptación de esta versión.</p>`);}
const rangeLabel=source=>{const r=levelRange(source);return r.min+'–'+r.max+' · centro '+r.center;};
const escapeText=text=>String(text).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function effectBadges(f){return fighterEffects(f).map(e=>`<span class="effect-chip effect-${e.tone}" title="${escapeText(e.title)}" aria-label="${escapeText(e.label+': '+e.title)}">${escapeText(e.label)}</span>`).join('');}
function combatEffects(f){const badges=effectBadges(f);return badges?`<span class="combat-effects" aria-label="Efectos de ${escapeText(name(byId[f.id]))}">${badges}</span>`:'';}
function passage(t,i){const r=t.run,now=gameNow();const phase=!r?'idle':r.status==='won'?'victory':r.status==='fallen'?'fallen':r.phase==='duel'?'duel':'walk';const members=r?r.fighters:t.ids.map(f=>fighter(byId[s.collection[f].id],s.collection[f]));const foes=r?.enemies||[];const lead=members.find(f=>f.hp>0);const displayMembers=phase==='duel'?(lead?[lead]:[]):members;const elapsed=r?Math.max(0,(now-(phase==='duel'?r.encounterAt:r.cycleStartedAt))/1000):0;const theme=ROUTE_THEMES[r?.route||0];const countdown=r?.status==='active'?Math.max(0,Math.ceil(((phase==='duel'?r.next:r.encounterAt)-now)/1000)):0;
return `<div class="pixel-passage ${phase} theme-${theme.key} gba-route" style="--scene-ratio:384 / ${[324,342,358][Math.floor((r?.route||0)/4)]};--atlas-x:${(r?.route||0)%4/3*100}%;--atlas-y:${[0,324/(1024-342)*100,100][Math.floor((r?.route||0)/4)]}%;--atlas-scale-y:${1024/[324,342,358][Math.floor((r?.route||0)/4)]*100}%;--hue:0deg;--sky:${theme.sky};--back:${theme.back};--ground:${theme.ground};--elapsed:-${elapsed}s;--travel:${r?.travelMs/1000||10}s" role="img" aria-label="Pasillo del equipo ${i+1}: ${phase==='duel'?'duelo':phase==='walk'?'avanzando':phase==='fallen'?'derrotado':'campamento'}"><div class="scene-art" aria-hidden="true"></div><div class="pixel-wall"></div><div class="pixel-floor"></div><div class="scene-scenery"><i></i><i></i><i></i></div><div class="pixel-torch left"></div><div class="pixel-torch right"></div><span class="passage-label">${phase==='duel'?'DUELO · CARGANDO MOVIMIENTOS':phase==='walk'?'AVANZANDO · encuentro en '+countdown+' s':phase==='victory'?'MEDALLA CONSEGUIDA':phase==='fallen'?'EQUIPO DEBILITADO':'CAMPAMENTO'}</span><div class="passage-party">${displayMembers.map((f,j)=>`<span class="pixel-member ${f.hp===0?'fainted':''}" style="--index:${j};--charge:${(f.chargeDuration||attackCharge(f))/1000}s">${phase==='duel'?`${combatEffects(f)}<span class="combat-name">${name(byId[f.id])} · Nv. ${f.level}</span>`:''}${img(byId[f.id],s.collection[f.family]?.shiny)}<span class="mini-hp" style="--hp-color:${f.hp/f.maxHp>.5?'#b7e08e':f.hp/f.maxHp>.2?'#f2ce87':'#ee8c81'}"><i style="width:${f.hp/f.maxHp*100}%"></i></span><span class="mini-exp" title="EXP al siguiente nivel"><i style="width:${xpProgress(s.collection[f.family]).percent}%"></i></span>${phase==='duel'&&f.queuedMove?`<span class="pixel-move">${moveById(f.queuedMove).name}</span><span class="mini-charge"><i style="width:${chargePercent(f)}%"></i></span>`:''}</span>`).join('')||'<span class="small">Forma tu equipo</span>'}</div><div class="passage-enemies">${foes.map((f,j)=>`<span class="pixel-member" style="--index:${j};--charge:${(f.chargeDuration||attackCharge(f))/1000}s">${phase==='duel'?combatEffects(f):''}<span class="combat-name">${name(byId[f.id])} · Nv. ${f.level}</span>${img(byId[f.id])}<span class="mini-hp" style="--hp-color:${f.hp/f.maxHp>.5?'#b7e08e':f.hp/f.maxHp>.2?'#f2ce87':'#ee8c81'}"><i style="width:${f.hp/f.maxHp*100}%"></i></span>${phase==='duel'&&f.queuedMove?`<span class="pixel-move">${moveById(f.queuedMove).name}</span><span class="mini-charge"><i style="width:${chargePercent(f)}%"></i></span>`:''}</span>`).join('')}</div><span class="pixel-vs">1 VS 1</span>${phase==='duel'&&weatherEffect(r?.weather)?`<span class="scene-weather">${weatherEffect(r.weather)}</span>`:''}${visibleDamageEvents(r?.visualEvents,now).map((e,j)=>`<span class="damage-number target-${e.side===0?'ally':'enemy'} ${e.kind==='heal'?'healing':damageTone(e.multiplier)}" style="--age:-${(now-e.at)/1000}s;--stack:${j%3}">${e.kind==='heal'?'+':'−'}${e.damage}<small>${e.kind==='heal'?'PS':'×'+e.multiplier}</small></span>`).join('')}</div>`;}
function reportForTeam(t,i,popup=false){const summary=t.run?expeditionSummary(t.run,gameNow()):t.lastSummary;if(!summary)return '';const destination=summary.kind==='gym'?GYMS[summary.gymIndex].label+' · '+RANKS[summary.rank].name:routes[summary.route].name;return summaryMarkup(summary,{destination,byId,moveById,sprite,teamIndex:i,key:popup?summaryKey(t.run):null});}
function teamCard(t,i){let r=t.run;const members=r?r.fighters:t.ids.map(f=>fighter(byId[s.collection[f].id],s.collection[f]));return `<article data-expedition-team="${i}" data-run-status="${r?.status||'idle'}" class="card expedition-card ${i>=slots(s)?'locked':''}"><div class="row"><span class="eyebrow">EQUIPO ${String(i+1).padStart(2,'0')}</span><span class="tag ${r?.status==='active'?'green':''}">${i>=slots(s)?'BLOQUEADO':r?.status==='active'?'EN EXPEDICIÓN':r?.status==='won'?'VICTORIA':r?.status==='fallen'?'DERROTADO':'EN CAMPAMENTO'}</span></div>${r&&r.status!=='active'&&!r.summaryDismissed?reportForTeam(t,i,true):''}${passage(t,i)}<details class="team-details" data-team="${i}" ${expandedTeams.has(i)?'open':''}><summary>Equipo · ${members.filter(f=>f.hp>0).length}/${members.length} en pie</summary><div class="individual-health">${members.map(f=>`<button class="health-chip ${f.hp===0?'fainted':''}" data-action="stats" data-id="${f.id}">${name(byId[f.id])}<span class="reserve-effects">${effectBadges(f)}</span><span>PS ${f.hp}/${f.maxHp} · Nv. ${f.level} · Vel. ${f.stats[5]}</span><span class="chip-hp" style="--hp-color:${f.hp/f.maxHp>.5?'#b7e08e':f.hp/f.maxHp>.2?'#f2ce87':'#ee8c81'}"><i style="width:${f.hp/f.maxHp*100}%"></i></span><span class="chip-exp"><i style="width:${xpProgress(s.collection[f.family]).percent}%"></i></span><span class="exp-text">${s.collection[f.family].level>=100?'EXP MÁX.':'EXP '+xpProgress(s.collection[f.family]).current+'/'+xpProgress(s.collection[f.family]).needed}</span></button>`).join('')}</div></details>${r?`<div class="row"><h3>${r.kind==='gym'?'Gimnasio '+GYMS[r.gymIndex].label+' · '+RANKS[r.rank].name:routes[r.route].name}</h3><span class="small">${r.kind==='gym'?'Ciclo '+(r.cycle+1)+' · '+(r.opponentIndex<3?'Entrenador '+(r.opponentIndex+1)+'/3':'Líder '+GYMS[r.gymIndex].name+' · '+(r.opponentIndex-2)+'/'+(r.rank+2))+' · '+r.drops+' sobres':r.step+' victorias · '+(r.drops||0)+' sobres'}</span></div><div class="bar"><i style="width:${r.hp/r.maxHp*100}%"></i></div><div class="run-meta">PS del equipo: ${r.hp} / ${r.maxHp}<br>${r.status==='won'?'Medalla conseguida · sin EXP extra':r.status==='fallen'?'El equipo cayó. No se generan más recompensas.':r.kind==='gym'?'Nivel efectivo máximo '+r.levelCap+' · recorrido '+(r.travelMs/1000).toFixed(1)+' s · Vel. zona '+r.zoneSpeed:'Recorrido '+(r.travelMs/1000).toFixed(1)+' s · Vel. zona '+(r.zoneSpeed||routes[r.route].speed)+' · sobres 20%'}</div><ol class="expedition-log" aria-label="Registro del equipo ${i+1}">${(r.logs||[]).slice(-5).reverse().map(l=>`<li class="${/EXP|experiencia/i.test(l.text)?'log-exp':/evoluci|aprendi|victoria|sobre/i.test(l.text)?'log-highlight':''}"><time>${new Date(l.at).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</time>${l.text.replace(/#(\d+)/g,(_,id)=>byId[id]?name(byId[id]):'#'+id)}</li>`).join('')}</ol>`:`<h3>${i>=slots(s)?'Requiere '+TEAM_BADGES[i]+' medallas':'Listo para explorar'}</h3><p class="small">Poder ${Math.round(teamPower(t))} · ${t.ids.length}/6 Pokémon${members.length?' · Vel. media '+teamSpeed(members).toFixed(1):''}</p>`}<div class="recovery-setting"><button class="secondary" data-action="toggleRevive" data-id="${i}" data-enabled="${t.autoRevive===false?'true':'false'}" ${i>=slots(s)||r?.status==='active'?'disabled':''}>Segunda oportunidad: ${t.autoRevive===false?'desactivada':'activada'}</button>${r||t.lastSummary?`<button class="secondary" data-action="runSummary" data-id="${i}">Ver resumen</button>`:''}${r?`<span class="small">${r.revives||0} revivires utilizados</span>`:''}</div><div class="actions">${i<slots(s)?r?`<button class="secondary" data-action="recall" data-id="${i}">${r.status==='fallen'?'Recuperar equipo':'Retirar equipo'}</button>`:`<button class="secondary" data-action="edit" data-id="${i}">Editar equipo</button><button data-action="send" data-id="${i}">Preparar expedición →</button>`:''}${i<slots(s)&&(t.lastRoute!==undefined||t.lastGym)&&r?.status!=='active'?`<button data-action="quick" data-id="${i}">⚡ Expedición rápida</button>`:''}</div></article>`;}
function pokeCard(p,collection=false){const c=s.collection[p.family],has=c?.unlocked.includes(p.id),shiny=!!(c?.shiny&&has);return `<article class="card poke specimen-card ${shiny?'shiny-card':''} ${has?'discovered':'undiscovered'}" data-tier="${tier(p.bst)}"><span class="number">#${String(p.species).padStart(4,'0')}</span><span class="tier-badge">${tier(p.bst)}</span>${shiny?'<span class="shiny-label">✦ SHINY</span>':''}<div class="specimen-stage">${img(p,shiny)}</div><h3>${name(p)}</h3><div class="specimen-types">${p.types.map(t=>typeBadge(t,TYPE_NAMES[t])).join('')}</div><div class="specimen-info"><span>${has?'Descubierto':'Por descubrir'}</span><span>Gen. ${p.generation}</span></div>${collection&&c?`<div class="collection-level"><b>Nv. ${c.level}</b><small>${c.level>=100?'EXP MÁX.':xpProgress(c).current+'/'+xpProgress(c).needed+' EXP'}</small></div><div class="collection-exp"><i style="width:${xpProgress(c).percent}%"></i></div><div class="collection-metrics"><span><small>PWT</small><b>${pwt(c,p)}</b></span><span><small>IV</small><b>${c.spent}/186</b></span><span><small>Puntos</small><b>${c.dust}</b></span></div>`:`<span class="specimen-base">${p.bst} PWB</span>`}<div class="specimen-actions"><button class="secondary" data-action="stats" data-id="${p.id}">Ver estadísticas</button>${collection&&c?`<button class="secondary" data-action="evolve" data-id="${p.family}">Evolución / forma</button>`:''}</div></article>`;}
function camp(){const list=owned(),width=Math.max(720,Math.ceil(Math.sqrt(list.length*1.5))*48);return `<div class="section-title"><h2>Prado de compañeros</h2><span class="small">${list.length} Pokémon · arrastra para explorar</span></div><div class="camp-viewport" tabindex="0" aria-label="Explorar prado de Pokémon"><div class="camp-ground gba-camp" style="width:${width}px;height:${Math.round(width*2/3)}px" aria-label="Todos tus Pokémon capturados pasean aquí">${list.map(([,c])=>{const m=campMotion(c.id,Date.now());return `<button class="camper" data-action="stats" data-id="${c.id}" style="left:${m.x}%;top:${m.y}%;z-index:${Math.floor(m.y)}" title="${name(byId[c.id])} · Nv. ${c.level}" aria-label="Ver ${name(byId[c.id])}"><span style="transform:translateY(-${m.bob}px) scaleX(${m.right?-1:1})">${img(byId[c.id],c.shiny)}</span></button>`}).join('')}<span class="camp-sign">CAMPAMENTO</span></div></div>`;}
function animateCamp(){if(view!=='home')return;for(const el of document.querySelectorAll?.('.camper')||[]){const m=campMotion(Number(el.dataset.id),Date.now());el.style.left=m.x+'%';el.style.top=m.y+'%';el.style.zIndex=Math.floor(m.y);el.firstElementChild.style.transform=`translateY(-${m.bob}px) scaleX(${m.right?-1:1})`;}}
function gymPreview(id,rank){const g=GYMS[id];if(!gymUnlocked(s,g,rank))return;const p=gymProgress(s,id),available=gymSpecies(s,catalog,g,rank),pool=gymPool(catalog,g,rank),speed=Math.round(5+1.2*gymLevel(g,rank));show(`<span class="eyebrow">GIMNASIO ${g.label} · ${RANKS[rank].name}</span><h2>${g.name}</h2><p>Tu nivel máximo: ${gymLevel(g,rank)+2} · Vel. zona ${speed}</p><p>3 entrenadores + líder con ${rank+2} Pokémon · ciclos hasta caer</p><p class="small">Niveles en sobres: ${rangeLabel({kind:'gym',gymId:id,rank})}</p><div class="gym-exclusive">${img(byId[g.exclusive])}<span>Exclusivo: ${name(byId[g.exclusive])}<br><small>${p.medal?'8% por sobre · garantía en '+(20-p.pity)+' sobres':'Consigue la medalla para desbloquearlo'}</small></span></div><p class="small">Sobres: entrenador 15% · líder 50% · primera medalla garantizado</p><label for="gym-team">Equipo disponible</label><select id="gym-team">${s.teams.slice(0,slots(s)).map((t,i)=>`<option value="${i}" ${t.run||!t.ids.length?'disabled':''}>Equipo ${i+1} · ${t.ids.length}/6${t.run?' · ocupado':!t.ids.length?' · vacío':' · '+(encounterDelay(t.ids.map(f=>fighter(byId[s.collection[f].id],{...s.collection[f],level:Math.min(s.collection[f].level,gymLevel(g,rank)+2)})),speed)/1000).toFixed(1)+' s'}</option>`).join('')}</select><div class="actions"><button data-action="gymBegin" data-id="${id}" data-rank="${rank}" ${s.teams.slice(0,slots(s)).some(t=>!t.run&&t.ids.length)?'':'disabled'}>Iniciar incursión</button><button class="secondary" data-action="gymPrepare">Preparar equipos</button></div><details><summary>Especies del sobre · ${available.length}/${pool.length}</summary><div class="route-pool">${available.map(p=>img(p)).join('')}</div><p class="small">Conserva especies anteriores y añade 5 de esta franja cada 2 líderes en ${RANKS[rank].name}. Plata: 3 líderes; Oro: 10 y una victoria en Plata.</p></details>`);}
function render(){const nav=document.querySelector('#nav'),navMarkup=Object.entries(labels).map(([v,l])=>`<button class="nav-item ${['home','teams','packs','dex'].includes(v)?'nav-primary':'nav-secondary'} ${view===v?'active':''}" data-view="${v}"><span class="nav-symbol" aria-hidden="true">${NAV_ICONS[v]}</span><span>${l.slice(3).trim()}</span></button>`).join('')+`<button class="nav-more ${['home','teams','packs','dex'].includes(view)?'':'active'}" data-action="more"><span class="nav-symbol" aria-hidden="true">•••</span><span>Más</span></button>`;
// Keep the same menu nodes between combat ticks so a touch can finish on its original button.
if(renderedNavView!==view){nav.innerHTML=navMarkup;renderedNavView=view;}document.querySelector('#wallet').innerHTML=`◉ ${s.coins.toLocaleString('es-CL')} &nbsp; ▱ ${totalPacks()} &nbsp; ◈ ${s.badges}/18`;
if(view==='home')app.innerHTML=`<span class="eyebrow">LA SIGUIENTE AVENTURA TE ESPERA</span><div class="actions"><button class="secondary" data-view="daily">Misiones diarias</button><button class="secondary" data-view="upgrades">Segunda oportunidad</button></div><div class="hero"><div class="hero-text"><span class="tag green">EXPEDICIONES INFINITAS</span><h1>Explora. Descubre.<br>Haz crecer tu equipo.</h1><p>Tu próxima aventura empieza aquí.</p><button data-view="teams">Preparar expedición →</button></div><img src="${art(byId[384])}" alt="Rayquaza"></div><div class="grid"><div class="card metric"><span class="eyebrow">FAMILIAS REUNIDAS</span><strong>${owned().length}<small> / 540</small></strong><small>${catalog.length} especies en el catálogo</small></div><div class="card metric"><span class="eyebrow">EXPEDICIONES EN CURSO</span><strong>${s.teams.filter(t=>t.run?.status==='active').length}<small> / ${slots(s)}</small></strong><small>Hasta seis equipos de seis Pokémon</small></div><div class="card metric"><span class="eyebrow">AURAS SHINY</span><strong>${owned().filter(([,c])=>c.shiny).length}</strong><small>+5% de poder permanente por familia</small></div></div>${camp()}<div class="section-title"><h2>Tus equipos</h2><button class="secondary" data-view="teams">Ver todos →</button></div><div class="grid two" id="home-teams">${s.teams.slice(0,2).map(teamCard).join('')}</div><div class="section-title"><h2>Circuito de tipos</h2><span class="small">${s.badges}/18 medallas</span></div><div class="card"><div class="type-medals">${GYMS.map(g=>`<span class="medal-item">${medal(g.type,g.label,gymProgress(s,g.id).medal)}<small>${g.label}</small></span>`).join('')}</div><div class="actions"><button data-view="gyms">Elegir gimnasio →</button><span class="small">${slots(s)<6?'Próximo equipo: '+TEAM_BADGES[slots(s)]+' medallas':'Seis equipos disponibles'}</span></div></div>`;
if(view==='teams')app.innerHTML=`<span class="eyebrow">EXPEDICIONES</span><h1>Seis equipos. Un mundo entero.</h1><p>1 vs 1 · hasta caer · rutas y gimnasios <button class="secondary" data-view="wiki">Cómo jugar</button></p><div class="section-title"><h2 id="team-slots">${slots(s)} espacios desbloqueados</h2><span class="small" id="team-medals">${s.badges}/18 medallas</span></div><div class="grid two" id="expedition-teams">${s.teams.map(teamCard).join('')}</div>`;
if(view==='routes')app.innerHTML=`<span class="eyebrow">ATLAS DE EXPLORACIÓN</span><h1>Elige tu siguiente destino.</h1><p>11 destinos · especies desbloqueables por victorias.</p><div class="grid route-grid">${routes.map(r=>{const available=routeSpecies(s,r),profile=routeProfile(s,r);return `<article class="card route-card ${!routeUnlocked(s,r)?'locked':''}">${routeBanner(r.id,'RUTA '+(r.id+1))}<div class="route-card-body"><div class="row"><span class="eyebrow">NIV. ${levelRange(r).min}–${levelRange(r).max}</span><span class="tag">${routeUnlocked(s,r)?'DISPONIBLE':'🔒 '+r.badge+' medallas'}</span></div><h3>${r.name}</h3><div class="route-type-list">${profile.types.slice(0,3).map(t=>typeBadge(t.type,TYPE_NAMES[t.type],Math.round(t.chance*100)+'%')).join('')}</div><div class="route-progress-head"><span>Especies desbloqueadas</span><b>${available.length}/${r.pool.length}</b></div><div class="bar"><i style="width:${available.length/r.pool.length*100}%"></i></div><div class="route-pool">${available.slice(0,6).map(p=>img(p)).join('')}</div><p class="small">${s.routeWins?.[r.id]||0} victorias · ${available.length>=r.pool.length?'Catálogo completo':'Próximo desbloqueo en '+(10-(s.routeWins?.[r.id]||0)%10)+' victorias'}</p><button class="secondary" data-action="pool" data-id="${r.id}">Ver Pokémon y probabilidades</button></div></article>`;}).join('')}</div>`;
if(view==='gyms')app.innerHTML=`<span class="eyebrow">CIRCUITO DE TIPOS</span><h1>18 tipos. 18 medallas.</h1><p>Elige tu especialidad · incursiones hasta caer · sin EXP</p><div class="team-unlocks">${TEAM_BADGES.map((n,i)=>`<span class="tag ${i<slots(s)?'green':''}">Equipo ${i+1} · ${i<slots(s)?'✓':n+' medallas'}</span>`).join('')}</div><div class="grid">${GYMS.map(g=>{const p=gymProgress(s,g.id),locked=!gymUnlocked(s,g);return `<article class="card gym-card ${locked?'locked':''}" style="--type-color:${TYPE_COLORS[g.type]}">${medal(g.type,g.label,p.medal)}<div class="row">${typeBadge(g.type,g.label)}<span class="tag ${p.medal?'green':''}">${p.medal?'◈ Medalla':locked?'🔒 '+g.badge+' medallas':'Por conquistar'}</span></div><h2>${g.name}</h2><div class="gym-exclusive">${img(byId[g.exclusive])}<span>Exclusivo<br><strong>${name(byId[g.exclusive])}</strong></span></div><p class="small">${p.cycles} líderes derrotados · garantía exclusiva: ${p.pity}/20 sobres</p><div class="gym-ranks">${RANKS.map((rank,j)=>`<button class="rank-${j} ${j?'secondary':''}" data-action="gym" data-id="${g.id}" data-rank="${j}" ${gymUnlocked(s,g,j)?'':'disabled'}>${rank.name} · Nv. ${gymLevel(g,j)+2}${gymUnlocked(s,g,j)?'':' 🔒'}</button>`).join('')}</div></article>`}).join('')}</div>`;
if(view==='packs')app.innerHTML=`<span class="eyebrow">RECOMPENSAS DE EXPLORACIÓN</span><h1>Abre tu próximo descubrimiento.</h1><p>3 Pokémon por sobre · rutas 20% · gimnasios por tipo · shiny 1/512.</p><div class="grid">${packSources.filter(r=>s.packs[r.id]>0).map(r=>`<article class="pack"><span class="eyebrow">${r.kind==='gym'?'SOBRE DE TIPO':'SOBRE DE RUTA '+(r.id+1)}</span>${packIllustration(r.kind==='gym'?GYMS[r.gymId].type:(routeProfile(s,r).types[0]?.type||12))}<h2>${r.name}</h2><p>${s.packs[r.id]} sobres disponibles · Nv. ${rangeLabel(r)}</p><div class="actions">${[1,10,50,1000].map(n=>`<button data-action="open" data-id="${r.id}" data-count="${n}">${n===1000?'Abrir todos (máx. 1.000)':'Abrir '+n}</button>`).join('')}</div></article>`).join('')||'<div class="card"><h3>Aún no hay sobres</h3><p>Completa combates en una expedición para conseguirlos.</p><button data-view="teams">Enviar equipo</button></div>'}</div>`;
if(view==='dex'){let list=filter==='owned'?owned().map(([,c])=>byId[c.id]):catalog;list=list.filter(p=>(gen==='all'||p.generation===Number(gen))&&(name(p).includes(query.toLowerCase())||String(p.species)===query));const pages=Math.ceil(list.length/60);page=Math.min(page,Math.max(0,pages-1));app.innerHTML=`<span class="eyebrow">ARCHIVO DEL ENTRENADOR</span><h1>Una Pokédex sin fronteras.</h1><p>${catalog.length} especies · 9 generaciones.</p><div class="search"><input id="search" placeholder="Buscar nombre o número…" value="${query.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}"><select id="filter"><option value="all" ${filter==='all'?'selected':''}>Todas las especies</option><option value="owned" ${filter==='owned'?'selected':''}>Mi colección</option></select><select id="gen"><option value="all">Todas las generaciones</option>${Array.from({length:9},(_,i)=>`<option value="${i+1}" ${gen==i+1?'selected':''}>Generación ${i+1}</option>`).join('')}</select></div><div class="catalog">${list.slice(page*60,page*60+60).map(p=>pokeCard(p,filter==='owned')).join('')}</div><div class="pagination"><button class="secondary" data-action="prev" ${page===0?'disabled':''}>←</button><span>${page+1} / ${pages||1} · ${list.length} resultados</span><button class="secondary" data-action="next" ${page>=pages-1?'disabled':''}>→</button></div>`;}
if(view==='wiki')app.innerHTML=`<span class="eyebrow">MANUAL DEL ENTRENADOR</span><h1>Wiki del juego.</h1><div class="grid two"><details class="card wiki-topic"><summary>IVs automáticos</summary><div class="wiki-content"><p>Básicos: 1 punto · primera evolución: 3 · segunda: 6. Se mejora siempre el IV más bajo, en orden PS → Ataque → Defensa → At. esp. → Def. esp. → Velocidad.</p><p>Coste = 1 + mejoras gastadas. Tope: 31 por atributo; los puntos sobrantes se guardan.</p></div></details><details class="card wiki-topic"><summary>EXP de primera generación</summary><div class="wiki-content"><p>EXP total por rival salvaje = ⌊EXP base × nivel / 7⌋. Principal: 50%; el otro 50% se divide entre reservas vivas. Solo uno vivo: 100%. Debilitados: 0. Redondeo hacia abajo.</p><p>Crecimiento normal para todos: EXP acumulada = nivel³. Las estadísticas se actualizan al subir de nivel durante la expedición; los debilitados permanecen debilitados. Kanto: EXP base original de Rojo/Azul; generaciones posteriores: PokéAPI.</p><a href="https://www.pokexperto.net/index2.php?seccion=mecanica/experience" target="_blank" rel="noopener" style="color:var(--green)">Referencia: Pokéxperto</a></div></details><details class="card wiki-topic"><summary>Evoluciones</summary><div class="wiki-content"><p>Si un sobre trae una forma más avanzada, tu compañero evoluciona inmediatamente aunque no alcance el nivel. Las cadenas sin ramificaciones también evolucionan automáticamente al alcanzar el nivel requerido. Las ramificadas se eligen en Pokédex → Mi colección → Evolución / forma. Conservas EXP, IVs, aura y un único compañero por familia. Las evoluciones por piedra, intercambio u otras condiciones usan niveles adaptados (25 o 40 cuando no existe nivel original).</p><h2>Gimnasios por tipo</h2><p>18 tipos, 18 medallas. Los seis iniciales están disponibles desde el comienzo; los grupos siguientes requieren 4 y 10 medallas. Cada ciclo contiene tres entrenadores de un Pokémon y un líder de 2/3/4 Pokémon según Bronce/Plata/Oro. Se repite hasta caer, sin curación entre combates, sin EXP ni monedas.</p><p>Entrenador: 15% de sobre; derrotar al líder completo: 50%. La primera victoria contra el líder garantiza un sobre y su medalla. Cada ciclo aumenta los niveles rivales en 2 (máximo 100) y sus estadísticas un 12% adicional, sin subir el límite de tu equipo. Puedes retirarte y repetir con el botón rápido.</p><p>Plata: medalla y 3 líderes derrotados en ese gimnasio. Oro: 10 líderes y al menos una victoria en Plata. Límites de PWB en sobres: Bronce 350, Plata 500, Oro sin límite. Cada categoría conserva las especies desbloqueadas de las anteriores y añade 5 de su nueva franja PWB. Añade otras 5 por cada 2 líderes derrotados en esa categoría.</p><p>El sobre contiene tres Pokémon del tipo, incluidos tipos dobles. Cada especie exclusiva se obtiene únicamente en su gimnasio: con la medalla, cada sobre tiene 8% de sustituir su primera carta por el exclusivo, garantizado como máximo cada 20 sobres. El contador se comparte entre categorías. El exclusivo no está sujeto al límite PWB. Los demás sorteos ponderan exp(−(PWB − mínimo)/120), con factor 0,15 para legendarios, ×(1 + 0,5 × etapa evolutiva) y ×3 para especies de la nueva franja en Plata/Oro.</p><p>Equipos: 0, 2, 5, 9, 13 y 18 medallas. Las medallas repetidas no cuentan dos veces. Cada cuenta comienza una partida nueva. El servidor calcula las expediciones offline hasta que caiga el equipo.</p><h2>Shiny = mejora permanente</h2><p>La primera captura shiny desbloquea Aura shiny: +5% de poder para toda su familia y apariencia shiny para sus evoluciones. Duplicados shiny no acumulan el bono.</p></div></details><details class="card wiki-topic"><summary>Distribución por poder base</summary><div class="wiki-content"><p>Cada especie no exclusiva ocupa un único intervalo PWB. Las 18 exclusivas de gimnasio se excluyen de los sobres y encuentros de ruta. Dentro de su ruta, peso = exp(−(PWB − mínimo)/30). Legendarios y singulares multiplican su peso por 0,15. Los pesos se normalizan dentro de las especies desbloqueadas. Se empieza con 5 especies y se añaden 5 cada 10 victorias acumuladas por ruta.</p><p>La tabla incluye todas las especies; se usan estadísticas actuales de PokéAPI.</p></div></details><details class="card wiki-topic"><summary>Segunda oportunidad y misiones</summary><div class="wiki-content"><p>Tres revivires mejorables: 3, 9 y 18 medallas; el siguiente requiere completar el anterior al 100%. Cada compra añade 10 puntos de probabilidad. Coste = 200 × 3^índice × siguiente nivel de mejora (1–10). Costes totales por revivir: 11.000, 33.000 y 99.000 monedas. Se elige la activación por equipo antes de salir. La expedición conserva esas probabilidades hasta terminar. Cada derrota intenta el siguiente revivir una sola vez; un fallo termina la expedición. Los éxitos curan a todo el equipo y eliminan estados negativos, conservando el rival y la dificultad. Tres revivires al 100% garantizan tres recuperaciones; la cuarta derrota termina el recorrido.</p><p>Misiones: 20 victorias de ruta, 3 sobres encontrados y un líder derrotado. Si empiezas el día sin medallas, el tercer objetivo es alcanzar 30 victorias de ruta. Las recompensas de misiones no cuentan como sobres encontrados. Cada misión entrega un sobre y reclamar las tres permite un bonus de ruta a elección. Se renuevan a medianoche de America/Santiago; las recompensas no reclamadas expiran. Los combates offline cuentan según la fecha de cada victoria y no se reproducen sorteos al sincronizar.</p><h2>Niveles de rutas y sobres</h2><p>Cada ruta tiene diez niveles posibles: cuatro por debajo de su centro y cinco por encima, dentro de 1–100. La primera abarca 1–10, con centro 5. Probabilidades desde el nivel mínimo: 1%, 3%, 8%, 18%, 30%, 22%, 11%, 5%, 1,5% y 0,5%. Las demás conservan su nivel central anterior, su catálogo y su velocidad exigida. En las primeras diez victorias acumuladas de la primera ruta, los rivales tienen 20% menos de estadísticas y se conserva la velocidad exigida de 9. Después usan sus estadísticas completas.</p><p>Los sobres de ruta usan los mismos niveles que los encuentros, con un sorteo por carta. Los de gimnasio usan el nivel base de su categoría como centro; el combate de gimnasio mantiene su balance anterior. Una familia nueva comienza al nivel sorteado, con EXP = nivel³. Un duplicado superior eleva el nivel y su EXP mínima; uno inferior conserva el progreso y se recicla. Ambos siguen aportando IVs. Las evoluciones de sobre siguen siendo directas aunque no cumplan el nivel, y subir por sobre puede producir evoluciones normales por nivel.</p><h2>Supervivencia & offline</h2><p>PWB = suma de estadísticas base. PWT = PWB + IVs actuales. El nivel y la aura se aplican aparte al combate, sin alterar PWT.</p><p>Se calculan PS, ataque, defensa y velocidad a partir del nivel y los IVs. Movimientos físicos/especiales, STAB ×1,5 y efectividad de tipos: ×0,5 / ×1 / ×2; doble tipo acumula factores. Inmunidad sustituida por daño ×0,1 (mínimo total). Los rivales se sortean dentro del rango de niveles de su ruta, con un solo rival por encuentro. El primer compañero vivo combate; si cae, entra el siguiente sin curar al rival. Cada zona exige Velocidad = redondear(5 + 1,2 × nivel de la zona). Se usa el promedio de la estadística Velocidad de los supervivientes, sin modificadores temporales del duelo. Hasta igualar la exigencia, el recorrido dura 15 s. Al superarla: tiempo = 15 / [1 + 0,5 × (velocidad del equipo / exigencia − 1)], mínimo 3 s. Doble velocidad: 10 s; triple: 7,5 s. Se recalcula después de cada encuentro. Cada movimiento carga según la velocidad individual. Sin curación entre victorias; sobre 20%.</p></div></details></div><div class="section-title"><h2>Disposición del catálogo</h2></div><div class="card"><table><tr><th>Ruta</th><th>Nivel recomendado</th><th>PWB</th><th>Especies</th><th>Medallas</th></tr>${routes.map(r=>`<tr><td>${r.name}</td><td>${rangeLabel(r)}</td><td>${r.min}–${r.max===Infinity?'∞':r.max-1}</td><td>${r.pool.length}</td><td>${r.badge}</td></tr>`).join('')}</table></div><div class="section-title"><h2>Combate y campamento</h2></div><div class="grid two"><details class="card wiki-topic"><summary>Números de daño</summary><div class="wiki-content"><p>Blanco: normal ×1. Azul: resistido ×0,5 o ×0,25. Rojo: eficaz ×2. Violeta: muy eficaz ×4. Gris: mínimo ×0,1. Verde: curación. El multiplicador también aparece bajo el número.</p><p>Cada ruta tiene un paisaje propio. Los números corresponden al daño real de cada ataque; no se reproducen golpes antiguos al volver al juego.</p></div></details><details class="card wiki-topic"><summary>Compañeros libres</summary><div class="wiki-content"><p>Todos tus Pokémon capturados pasean por el prado. Pulsa uno para ver sus estadísticas. Toda la colección comparte un solo mapa, que crece con tus capturas. Puedes desplazarte por el prado; es una vista de la colección y no altera las expediciones.</p><h3>Curación y absorción</h3><p>Drenadoras quita 1/8 de los PS máximos del rival al terminar su acción y cura al compañero activo por los PS realmente quitados. Si el rival está al borde de caer, absorbe solo lo que le queda. Se reinicia por encuentro y no se acumula al repetir el movimiento. Arraigo y Acua Aro recuperan 1/16 de PS máximos después de cada acción; cada efecto se aplica una sola vez, aunque pueden coexistir. Absorber y similares recuperan su porcentaje del daño real. La curación nunca supera los PS máximos, no revive debilitados y respeta el bloqueo de curación. Los números verdes muestran cada curación real, también la causada por Drenadoras durante la acción rival. Los movimientos de curación directa y Descanso tienen 2 s extra de carga base; Drenadoras, Arraigo y Acua Aro, 1 s extra. La velocidad reduce la carga total.</p><h3>Estados y cambios de atributos</h3><p>Los indicadores encima del nombre de cada Pokémon muestran estados, barreras y cambios de estadísticas de ambos Pokémon. Verde ↑: aumento; naranja ↓: reducción, de −6 a +6. Los números en sueño, confusión, somnolencia y canto mortal cuentan acciones pendientes, no segundos. Los efectos desaparecen cuando se curan o reinician en el motor de combate. El desplegable del equipo muestra también los estados de las reservas.</p><h3>Resumen al terminar</h3><p>Cada expedición completada deja un resumen sobre su panel con EXP por compañero, niveles, evoluciones y movimientos aprendidos. Puedes cerrarlo sin perder las recompensas y volver a consultarlo. No bloquea la navegación. Los cambios por sobres durante el recorrido se distinguen de la EXP de combate. Las expediciones anteriores solo disponen del detalle registrado desde esta actualización.</p><h3>Equipo recomendado por ruta</h3><p>Primero elige y confirma la ruta; después revisa el equipo y confirma la salida. El recomendador utiliza las especies actualmente desbloqueadas y su frecuencia real de encuentro: actualmente todas tienen la misma probabilidad dentro de ese catálogo. Los porcentajes indican presencia de cada tipo; un Pokémon de doble tipo cuenta en ambos. Se evalúan los movimientos equipados, daño y carga, PS, defensas, curación, nivel, IVs y aura, con un pequeño aporte por rapidez de recorrido. Se eligen los seis mejores índices individuales, sin exigir un tipo concreto; es una estimación, no una garantía de victoria. Excluye Pokémon asignados a otros equipos. Puedes cambiar integrantes y orden antes de salir; tus movimientos equipados se conservan.</p><h3>Movimientos</h3><p>Todas las especies conservan sus movimientos nativos. Si no tienen nuevos aprendizajes después del nivel 5 o su repertorio tiene menos de cuatro movimientos, reciben aprendizajes de entrenamiento en niveles 10, 20, 35 y 50, usando ataques normales adaptados a su mejor atributo ofensivo. Hasta cuatro equipados. Se usan en orden 1 → 2 → 3 → 4 y se repite la secuencia; cada duelo empieza en el primero. Los aprendizajes por nivel se incorporan automáticamente. La recomendación automática elige movimientos; también puedes equiparlos manualmente. La Velocidad reduce la carga individual y el recorrido del equipo.</p></div></details></div>`;
if(view==='upgrades')app.innerHTML=`<span class="eyebrow">MEJORAS PERMANENTES</span><h1>Segunda oportunidad.</h1><p>Hasta tres revivires por expedición. Cada intento fallido termina el recorrido.</p><div class="grid">${REVIVE_BADGES.map((badges,i)=>{const u=reviveUpgrade(s,i);return `<article class="card recovery-card ${u.unlocked?'':'locked'}"><span class="recovery-node">${i+1}</span><span class="eyebrow">REVIVIR ${i+1}</span><h2>${u.chance}% de activación</h2><div class="bar"><i style="width:${u.chance}%"></i></div><p>${u.unlocked?'Mejora permanente para todos tus equipos':badges+' medallas'+(i?' · revivir anterior al 100%':'')}</p><button data-action="reviveUpgrade" data-id="${i}" ${u.canBuy?'':'disabled'}>${u.maxed?'Completado':(u.level?'Mejorar a '+(u.chance+10)+'%':'Desbloquear al 10%')+' · '+u.cost.toLocaleString('es-CL')+' ◉'}</button></article>`;}).join('')}</div><p class="small">Elige la activación por equipo antes de salir. Las mejoras compradas se aplican a las nuevas expediciones.</p>`;
if(view==='daily'){const d=ensureDaily(s,gameNow());renderedDailyDay=d.day;const objectives=dailyObjectives(s,gameNow()),choices=routes.filter(r=>routeUnlocked(s,r));app.innerHTML=`<span class="eyebrow">OBJETIVOS DIARIOS</span><h1>Una nueva meta cada día.</h1><p>Renovación a medianoche de Chile · ${d.day} · progreso offline incluido.</p><label for="daily-route">Ruta para sobres a elección</label><select id="daily-route">${choices.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select><div class="grid daily-grid">${objectives.map(m=>`<article class="card daily-card ${m.claimed?'claimed':m.complete?'complete':''}"><span class="eyebrow">MISIÓN ${m.id+1}</span><h2>${m.label}</h2><p><b class="daily-value" data-mission="${m.id}">${m.value}/${m.target}</b></p><div class="bar"><i class="daily-bar" data-mission="${m.id}" style="width:${m.value/m.target*100}%"></i></div><p class="daily-reward">▱ ${m.reward}</p><button data-action="dailyClaim" data-id="${m.id}" data-day="${d.day}" ${m.claimed||!m.complete?'disabled':''}>${m.claimed?'Reclamado':'Reclamar sobre'}</button></article>`).join('')}</div><div class="card daily-bonus"><h2>Completa las tres</h2><p>Un sobre adicional de la ruta elegida. Hasta cuatro sobres diarios.</p><button data-action="dailyClaim" data-id="3" data-day="${d.day}" ${d.claimed[3]||!d.claimed.slice(0,3).every(Boolean)?'disabled':''}>${d.claimed[3]?'Bonus reclamado':'Reclamar bonus'}</button></div>`;}
if(view==='account')app.innerHTML=`<span class="eyebrow">TU PARTIDA</span><h1>Cuenta de entrenador.</h1><div class="card"><h2>${escapeText(cloudUser?.name||'Entrenador')}</h2><p>La misma cuenta en PC y celular. La preparación se guarda en segundo plano. Las expediciones y los sobres se confirman en el servidor.</p><p>${cloudError||syncState.error||syncState.pending?'Sincronización pendiente':'Partida sincronizada'} · ${new Date(s.last).toLocaleString('es-CL')}</p><div class="actions"><button data-action="syncNow">Sincronizar ahora</button><a class="account-link" href="/signout-with-chatgpt?return_to=%2F" target="_top">Cerrar sesión</a></div></div>`;
if(cloudReady&&!s.starterId&&!owned().length)app.innerHTML=`<span class="eyebrow">UN NUEVO COMIENZO</span><h1>Elige tu primer compañero.</h1><p>Un inicial de cualquiera de las nueve generaciones. Elige su tipo pensando en las primeras expediciones; comenzarás con un único Pokémon.</p><div class="catalog">${starters.map(p=>`<article class="card poke">${img(p)}<h3>${name(p)}</h3><p>${p.types.map(t=>TYPE_NAMES[t]).join(' / ')} · Gen. ${p.generation}</p><span class="tag">${p.bst} PWB · ${p.bst} PWT</span><div class="actions"><button data-action="starter" data-id="${p.id}">Elegir</button></div></article>`).join('')}</div>`;
if(!cloudReady){document.querySelector('#nav').innerHTML='';renderedNavView=null;document.querySelector('#wallet').innerHTML='';app.innerHTML=`<section class="welcome-hero"><span class="eyebrow">POKÉMON EXPEDITION</span><h1>Tu aventura continúa.<br>Estés donde estés.</h1><p>Explora rutas, reúne compañeros y conquista los 18 tipos.</p><div class="welcome-art" aria-hidden="true"></div></section><div class="card account-card welcome-account"><p>Inicia sesión para elegir tu inicial y guardar tu partida. Usa la misma cuenta de ChatGPT en el PC y el celular.</p><a class="account-link primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Entrar con ChatGPT →</a>${cloudError?`<p class="small">${escapeText(cloudError)}</p><button class="secondary" data-action="retryCloud">Reintentar conexión</button>`:''}</div>`;}

for(const button of document.querySelectorAll?.('[data-action]')||[]){if(syncState.critical&&['starter','pick','order','equip','recommend','begin','recall','quick','gymBegin','open','evolveChoice','form','reviveUpgrade','toggleRevive','dailyClaim','dismissSummary','setRoute','autoTeam'].includes(button.dataset.action)){button.disabled=true;button.setAttribute('aria-busy','true');}}
}
if(cloudReady)advance(s,routes,gameNow(),chart);save();render();
function showPackResults(batch){const groups=new Map();for(const x of batch.results){const key=x.p.id+':'+x.shiny+':'+x.level;const old=groups.get(key)||{...x,copies:0};old.copies++;groups.set(key,old);}show(`<span class="eyebrow">APERTURA MÚLTIPLE</span><h2>${batch.count} sobres · ${batch.results.length} Pokémon</h2><p>${batch.results.filter(x=>x.shiny).length} shiny · IVs aplicados automáticamente. Resultados agrupados por especie y apariencia.</p><div class="catalog">${[...groups.values()].map(x=>`<div class="card poke pack-reveal ${x.shiny?'shiny-card':''}" data-tier="${tier(x.p.bst)}"><div class="specimen-stage">${img(x.p,x.shiny)}</div><h3>${name(x.p)} ${x.shiny?'★':''} ×${x.copies}</h3><span class="tag">Nv. ${x.level??5} · ${tier(x.p.bst)} · ${x.p.bst} PWB</span><p>Nivel en colección ${s.collection[x.p.family].level} · PWT actual ${pwt(s.collection[x.p.family],x.p)} · ${x.result}</p></div>`).join('')}</div>`); }
function show(html){modal.innerHTML='<div class="modal-frame"><div class="modal-toolbar"><button class="secondary" data-action="close" aria-label="Cerrar ventana">Cerrar ×</button></div><div class="modal-content">'+html+'</div></div>';if(!modal.open)modal.showModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.closest?.('.camp-viewport')?.dataset.dragged)return;if(b.dataset.view){navigationRevision++;view=b.dataset.view;modal.close();render();return}const id=Number(b.dataset.id),act=b.dataset.action;
if(act==='more'){show(`<span class="eyebrow">TU AVENTURA</span><h2>Explora el campamento</h2><div class="more-menu">${Object.entries(labels).filter(([v])=>!['home','teams','packs','dex'].includes(v)).map(([v,l])=>`<button class="secondary" data-view="${v}"><span>${NAV_ICONS[v]}</span>${l.slice(3).trim()} →</button>`).join('')}</div>`);return;}
if(act==='syncNow'||act==='retryCloud'){await refreshCloud();render();return;}
if(!cloudReady)return;
if(['starter','pick','order','equip','recommend','begin','recall','quick','gymBegin','open','evolveChoice','form','reviveUpgrade','toggleRevive','dailyClaim','dismissSummary','setRoute','autoTeam'].includes(act)){const action={...b.dataset,type:act};delete action.action;if(act==='gymBegin')action.team=document.querySelector('#gym-team')?.value||'0';if(act==='dailyClaim')action.route=document.querySelector('#daily-route')?.value||'0';await sendCommand(action);return;}

if(act==='close')modal.close();
if(act==='stats'){const p=byId[id],c=s.collection[p.family],progress=c||{level:5,iv:[0,0,0,0,0,0],shiny:false};const f=fighter(p,progress);show(`<span class="eyebrow">FICHA DEL POKÉMON</span><h2>${name(p)}</h2><div class="stat-portrait">${img(p,c?.shiny)}</div><p>${p.types.map(t=>TYPE_NAMES[t]).join(' / ')} · Nivel ${f.level}${c?'':' (referencia sin capturar)'}</p><p>EXP total: ${xpProgress(progress).total} · ${f.level>=100?'Nivel máximo':'Siguiente nivel: '+(f.level+1)**3+' EXP totales'}</p><div class="row"><span class="tag">PWB ${p.bst}</span><span class="tag green">PWT ${pwt(progress,p)}</span></div><table><tr><th>Estadística</th><th>Base</th><th>IV</th><th>Al nivel actual</th></tr>${IV_NAMES.map((label,j)=>`<tr><td>${label}</td><td>${p.stats[j]}</td><td>${progress.iv[j]}</td><td>${f.stats[j]}</td></tr>`).join('')}</table><p>PS: vida individual. Ataque y At. especial se enfrentan a Defensa y Def. especial. Cada movimiento tiene categoría física o especial; los de apoyo hacen daño bajo y aplican efectos adicionales.</p><p>Velocidad: reduce el recorrido del equipo y el tiempo de carga individual. Cuatro movimientos equipados como máximo. Los aprendizajes por nivel se incorporan automáticamente.</p>${c?`<button data-action="moves" data-id="${p.id}">Gestionar movimientos (${c.equippedMoves?.length||0}/4)</button>`:''}`);}

if(act==='runSummary'){show(reportForTeam(s.teams[id],id));}
if(act==='gymPrepare'){modal.close();view='teams';}
if(act==='edit'){if(routes[s.teams[id].plannedRoute])teamEditor(id);else chooseRoute(id);}
if(act==='moves')moveEditor(id);
if(act==='send')chooseRoute(id);
if(act==='gym')gymPreview(id,Number(b.dataset.rank)||0);
if(act==='pool'){const r=routes[id],available=routeSpecies(s,r),ids=new Set(available.map(p=>p.id));const weights=available.map(p=>Math.exp(-(p.bst-r.min)/30)*(p.legendary?.15:1)),sum=weights.reduce((a,b)=>a+b,0);show(`<h2>${r.name}</h2><p>${available.length}/${r.pool.length} especies desbloqueadas · ${s.routeWins?.[id]||0} victorias acumuladas. Cinco especies iniciales; cinco más cada diez victorias. Los rivales y sobres usan el mismo catálogo desbloqueado.</p><p>Niveles: ${levelDistribution(r).map(x=>x.level+': '+x.chance+'%').join(' · ')}</p><div class="catalog">${[...r.pool].sort((a,b)=>a.bst-b.bst||a.id-b.id).map((p,i)=>`<div class="card poke ${ids.has(p.id)?'':'species-locked'}">${img(p)}<h3>${name(p)}</h3><span class="tag">${p.bst} PWB · ${ids.has(p.id)?(weights[available.findIndex(x=>x.id===p.id)]/sum*100).toFixed(3)+'%':'🔒 '+Math.floor(i/5)*10+' victorias'}</span></div>`).join('')}</div>`);}
if(act==='evolve'){if(s.teams.some(t=>t.run?.status==='active'&&t.ids.includes(id)))return toast('Retira el equipo antes de elegir una evolución');const c=s.collection[id],options=evolutionOptions(c);show(`<h2>Evoluciones de ${name(byId[c.id])}</h2><p>Nivel ${c.level} · conserva EXP, IVs y aura shiny.</p><div class="picker">${options.map(o=>`<button data-action="evolveChoice" data-id="${id}" data-pokemon="${o.p.id}" ${c.level<o.level?'disabled':''}>${img(o.p,c.shiny)}${name(o.p)}<br>Nv. ${o.level}${o.adapted?' · requisito adaptado':''}</button>`).join('')||'<p>Esta forma no tiene evoluciones posteriores.</p>'}</div><h3>Formas descubiertas</h3><div class="picker">${c.unlocked.map(pid=>`<button data-action="form" data-id="${id}" data-pokemon="${pid}">${img(byId[pid],c.shiny)}${name(byId[pid])}</button>`).join('')}</div>`);}
if(act==='next')page++;if(act==='prev')page--;
save();render();});
document.addEventListener('change',e=>{if(e.target.id==='team-sort'){teamSort=e.target.value;teamEditor(editTeamId)}if(e.target.id==='team-type'){teamType=e.target.value;teamEditor(editTeamId)}if(e.target.id==='filter'){filter=e.target.value;page=0;render()}if(e.target.id==='gen'){gen=e.target.value;page=0;render()}});
document.addEventListener('input',e=>{if(e.target.id==='team-query'){teamQuery=e.target.value;teamEditor(editTeamId);const field=document.querySelector('#team-query');field?.focus();field?.setSelectionRange(teamQuery.length,teamQuery.length)}if(e.target.id==='search'){query=e.target.value;page=0;const pos=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)}});
setInterval(()=>{if(!cloudReady)return;const activeTeams=s.teams.map(t=>t.run?.status==='active'),active=activeTeams.some(Boolean);if(cloudReady)advance(s,routes,gameNow(),chart);if(activeTeams.some((was,i)=>was&&s.teams[i].run?.status==='fallen'))refreshCloud();if(active){document.querySelector('#wallet').innerHTML=`◉ ${s.coins.toLocaleString('es-CL')} &nbsp; ▱ ${totalPacks()} &nbsp; ◈ ${s.badges}/18`;if(Date.now()-lastAutoSave>=1000){save();lastAutoSave=Date.now();}if(!pointerHeld&&Date.now()>=interactionUntil){const teams=document.querySelector(view==='teams'?'#expedition-teams':view==='home'?'#home-teams':'#no-live-teams');if(teams)patchExpeditionPanels(teams,view==='teams'?s.teams:s.teams.slice(0,2),teamCard);if(view==='teams'){const heading=document.querySelector('#team-slots'),medals=document.querySelector('#team-medals');if(heading)heading.textContent=slots(s)+' espacios desbloqueados';if(medals)medals.textContent=s.badges+'/18 medallas';}}}animateCamp();},200);

function updateDailyProgress(){if(view!=='daily'||!cloudReady)return;const d=ensureDaily(s,gameNow());if(renderedDailyDay!==d.day&&!pointerHeld){render();return;}for(const m of dailyObjectives(s,gameNow())){const value=document.querySelector('.daily-value[data-mission="'+m.id+'"]'),bar=document.querySelector('.daily-bar[data-mission="'+m.id+'"]'),button=document.querySelector('[data-action="dailyClaim"][data-id="'+m.id+'"]');if(value)value.textContent=m.value+'/'+m.target;if(bar)bar.style.width=m.value/m.target*100+'%';if(button)button.disabled=syncState.critical||m.claimed||!m.complete;}}
setInterval(updateDailyProgress,1000);
let campDrag=null;
document.addEventListener('pointerdown',e=>{pointerHeld=true;const area=e.target.closest?.('.camp-viewport');if(!area||e.button>0)return;campDrag={area,x:e.clientX,y:e.clientY,left:area.scrollLeft,top:area.scrollTop,moved:false};});
document.addEventListener('pointermove',e=>{if(!campDrag)return;const d=campDrag,dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.abs(dx)+Math.abs(dy)>8)d.moved=true;if(d.moved){d.area.scrollLeft=d.left-dx;d.area.scrollTop=d.top-dy;}});
document.addEventListener('pointerup',()=>{pointerHeld=false;interactionUntil=Date.now()+350;if(campDrag?.moved){campDrag.area.dataset.dragged='true';const area=campDrag.area;setTimeout(()=>delete area.dataset.dragged,0);}campDrag=null;});
document.addEventListener('pointercancel',()=>{pointerHeld=false;interactionUntil=Date.now()+350;campDrag=null;});

document.addEventListener('toggle',e=>{if(!e.target.classList?.contains('team-details'))return;const index=Number(e.target.dataset.team);if(e.target.open)expandedTeams.add(index);else expandedTeams.delete(index);},true);

setInterval(()=>{if(cloudReady&&s.teams.some(t=>t.run?.status==='active'))refreshCloud();},300000);
document.addEventListener('visibilitychange',()=>{if(!cloudReady)return;if(document.visibilityState==='visible')refreshCloud();else sync.flush();});
